#!/usr/bin/env python3
"""Static review pages (grouped contact sheets + assembled samples). Plain HTML/CSS, no script, no audio. Art sits behind exact native SVG."""
import json, os, html
W='/home/elderle/amf-work/amf-ajourne-m05/'; P=W+'public/soundscape/m05/sheets/'; os.makedirs(P,exist_ok=True)
D=json.load(open(W+'lib/soundscape/resources/interval-data.json'))['cards']; AT=json.load(open(W+'lib/soundscape/resources/atlas.json'))
NR=json.load(open(W+'docs/m05/native_registry.json'))
strip=lambda n:''.join(ch for ch in n if not ch.isdigit())
CSS="""*{box-sizing:border-box}body{margin:0;background:#f9f5ed;color:#5c465b;font:17px/1.6 Georgia,'Times New Roman',serif}main{max-width:1080px;margin:0 auto;padding:22px clamp(14px,4vw,40px) 60px}
h1{font-weight:400;font-size:clamp(28px,5vw,44px);line-height:1.1;color:#4c2748;margin:.2em 0 .1em}h2{font-weight:400;color:#4c2748;font-size:24px;margin:0 0 4px}.eyebrow{font:700 11px ui-sans-serif,system-ui,sans-serif;letter-spacing:.2em;text-transform:uppercase;color:#a3778f}
.lede{max-width:62ch}.item{margin:34px 0;padding-top:22px;border-top:1px solid #e6dccb}.meta{font:12.5px ui-sans-serif,system-ui,sans-serif;color:#786a75;margin:0 0 10px}
.row{display:grid;grid-template-columns:minmax(0,1fr);gap:18px;align-items:center}@media(min-width:860px){.row{grid-template-columns:minmax(0,5fr) minmax(0,6fr)}}
.fig{position:relative;margin:10px auto;width:100%}.fig .art{display:block;margin:0 auto 6px;max-width:100%;max-height:250px;width:auto;height:auto}.fig .nat{position:relative;z-index:1;display:block;width:100%;height:auto}
.fig.wide .art{max-height:230px}
.how{font:15.5px/1.55 ui-sans-serif,system-ui,sans-serif;color:#4a3a4a}.how b{color:#6d326e}.guard{font:13px/1.5 ui-sans-serif,system-ui,sans-serif;color:#786a75;border-left:3px solid #e9ae7c;padding:4px 10px;margin-top:10px}
details{font:13px ui-sans-serif,system-ui,sans-serif;color:#786a75;margin-top:8px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:22px}.card{background:rgba(255,250,243,.7);border:1px solid #eadfcd;border-radius:14px;padding:12px}
.icons{display:flex;flex-wrap:wrap;gap:14px}.icons figure{margin:0;text-align:center;font:12px ui-sans-serif,system-ui,sans-serif;width:84px}.icons img{width:64px;height:64px}
.banner{width:100%;height:auto;display:block}nav.sheets{font:14px ui-sans-serif,system-ui,sans-serif;margin:6px 0 16px}nav.sheets a{margin-right:14px;color:#6d326e}
.ch{max-width:760px}.ch h3{font:700 12px ui-sans-serif,system-ui,sans-serif;letter-spacing:.16em;text-transform:uppercase;color:#a3778f;margin:22px 0 4px}.src{background:#fffaf3;border:1px solid #eadfcd;border-radius:10px;padding:2px 14px;margin:8px 0}
@media print{.fig .art{display:none}}"""
NAV='<nav class="sheets"><a href="systems.html">Systems</a><a href="intervals.html">13 intervals</a><a href="comparisons.html">Comparisons</a><a href="support.html">Support</a><a href="assembled.html">Assembled samples</a></nav>'
def page(name,title,body,lede=''):
    open(P+name,'w').write(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} · Interval Palette art review</title><style>{CSS}</style></head><body><main><p class="eyebrow">Ajourné · Interval Palette · M05 asset review (not live)</p><h1>{html.escape(title)}</h1>{NAV}<p class="lede">{lede}</p>{body}</main></body></html>')
def fig(art,nat,cls='',alt=''):
    ti=NR[nat.replace('.svg','')]['title'] if False else ''
    a=''.join(f'<img class="art" src="../art/{x}.webp" alt="" aria-hidden="true" style="display:inline-block;max-width:48%;margin:0 1%">' if '+' in art else f'<img class="art" src="../art/{x}.webp" alt="" aria-hidden="true">' for x in art.split('+')) if art else ''
    if '+' in art: a=f'<div style="text-align:center">{a}</div>'
    return f'<div class="fig {cls}">{a}<img class="nat" src="../native/{nat}.svg" alt="{html.escape(alt)}"></div>'
def desc(nat): return NR[nat]['desc']
def item(idn,title,cls,art,nat,how,own,guard,fc=''):
    return f'<section class="item" id="{idn}"><p class="eyebrow">{idn} · {cls}</p><h2>{html.escape(title)}</h2><p class="meta">art: {art.replace('+',' + ') or "none"} · native: {nat}.svg (+ .print.svg)</p><div class="row"><div>{fig(art,nat,fc,desc(nat))}</div><div class="how"><p><b>How to read the picture.</b> {how}</p><p><b>On your own keyboard.</b> {own}</p><div class="guard">{guard}</div><details><summary>Alt text of the exact figure</summary>{html.escape(desc(nat))}</details></div></div></section>'
# ---------- systems
S=[('IPV-01','Palette landing hero','SYSTEM · ART + NATIVE','IPV-01','IPV-07-native','The painting is only an invitation: warm centre, then wider and wider fields. The exact ruler is the figure beneath: thirteen labelled landmarks from 0 to 12 semitones above C4.','Find the C nearest the middle of your keyboard. Play it, then play the next key up, then the one after. Count the keys you have moved: that is the interval growing.','The painted rings are not calibrated; only the labelled ruler carries measured distance.','wide'),
('IPV-04','What is an interval?','SYSTEM · ART + NATIVE','IPV-04','IPV-04-native','Two soft presences with a stream between them stand for two notes and the distance between them. The keyboard under it measures one example exactly: C to E is four semitones.','Play C, then E, with your own hands. Now count the keys between them, black keys included, until you reach four.','The width of the painted passage does not measure semitones.',''),
('IPV-05','Melodic versus harmonic','SYSTEM · ART + NATIVE','IPV-05','IPV-05-native','Left: the same two notes one after another along time. Right: the same two notes at once. The strips show C and E both ways, so you can see the pitch pair has not changed, only the timing.','Play C then E, slowly. Then press both together. Notice how the same two keys feel different in time.','Melodic and harmonic versions name the same distance.','wide'),
('IPV-06','Keyboard interval orientation','SYSTEM · NATIVE + ART','IPV-04','IPV-06-native','Black keys come in groups of two and three. C to D has a black key between, so it is two semitones. E to F has none, so it is one. White neighbours are not always one semitone.','Find a group of two black keys; the white key just left of it is C. Play C to D, then E to F, and notice one has a black key between and the other does not.','Letter names and semitone counts are different counts.',''),
('IPV-07','Interval family ruler','SYSTEM · ART + NATIVE','IPV-01','IPV-07-native','Thirteen landmarks sit on one exact ruler from 0 to 12 semitones above C4, labelled with the standard abbreviations. Position is distance only.','Pick any landmark, find C4 on your keyboard, count that many keys up and play the result.','The order is by measured distance, not by tension or mood.','wide'),
('IPV-08','Shared-note relationship web','SYSTEM · ART + NATIVE','IPV-08','IPV-34-native','The painting shows one shared anchor with different upper notes branching off. The exact figure beside it shows the idea with real keys: keep C, change the other note.','Hold C down quietly and move only your other finger between neighbouring keys. Notice that C is a fixed reference while the relationship changes.','Blending is context-dependent; this figure measures notes, not feelings.',''),
('IPV-09','Comparison diptych layout','SYSTEM · VARIANT (layout)','IPV-25','IPV-09-native','A reusable pattern: one anchor stays, one note changes, and the semitone difference is printed from the data. This example compares a fourth and a fifth.','Play C with F, then C with G, and count the keys the upper note travelled.','Reusable layout, not an extra image call.','wide')]
page('systems.html','Systems',''.join(item(i,t,c,a,n,h,o,g,f) for i,t,c,a,n,h,o,g,f in S),'Shared illustrations: the landing hero, what an interval is, melodic versus harmonic, keyboard orientation, the family ruler, the shared-note web and the comparison pattern.')
# ---------- 13 intervals
G13={0:'Same pitch in the same register. Voices can still differ in timbre.',1:'Very close spacing. Roughness depends on register and sound, not a rule.',2:'One whole step. Not every pair of white keys is a whole step (E to F is one semitone).',3:'Three semitones. Often a member of a minor triad, but no mood is prescribed.',4:'Four semitones. Contextual: it is a major triad member, not a happiness law.',5:'Five semitones. Its role depends on context; it is not always stable or always tense.',6:'Exactly half the octave. F♯ above C is an augmented fourth; G♭ above C is a diminished fifth. Same key.',7:'Seven semitones. In equal temperament it is not the pure 3:2 ratio.',8:'Eight semitones: the inversion of the major third.',9:'Nine semitones: the inversion of the minor third.',10:'Ten semitones. Resolution is context, not a property of the interval.',11:'C to B is eleven semitones; the single-semitone step is B up to C5, which is a different move.',12:'Same pitch name, different register: not the same as unison.'}
rows=''
for c in D:
    n=c['semitones']; idn=10+n; up=strip(c['sourceUpper']['name']); lo='C'
    how=f"The painting suggests the relationship; the keyboard is exact. {lo}4 is the lower key and {up}4{'' if n<12 else ''} is the upper key, {n} semitone{'s' if n!=1 else ''} apart. Follow the numbered hops from the lower key to the upper."
    if n==0: how="The painting layers two voices on one place. The keyboard shows a single highlighted key because both notes are the same pitch."
    own=f"Play C4, then {up}{'5' if n==12 else '4'}, one after another, then together. Count the hops yourself on the keys, then notice what you hear without judging it good or bad." if n else "Play C4 and sustain it, then play it again. Notice that nothing moved: the interval is zero."
    rows+=item(f'IPV-{idn}',f"{c['intervalName']} ({c['abbreviation']}) · source {c['id']}",'INTERVAL · ART + NATIVE',f'IPV-{idn}',f'IPV-{idn}-native',how,own,G13[n],'sq')
page('intervals.html','The thirteen intervals',rows,'IPV-10 to IPV-22 map one-to-one to source cards IP-00 to IP-12 (IPV-10 = IP-00, not IP-10). Every painting is art only; every key, label and count comes from the source data.')
# ---------- comparisons
C=[('IPV-23','Minor versus major second','IPV-23-native','IPV-11+IPV-12','C to D♭ is 1 semitone; C to D is 2. The lower note stays and the upper note moves one key.','Play C with D♭, then C with D. Count the extra key.','Compares one extra semitone, not a pleasantness score.'),
('IPV-24','Minor versus major third','IPV-24-native','IPV-13+IPV-14','Keep C. E♭ is three semitones above it, E is four. One key of difference.','Play C with E♭, then C with E. Notice only one finger moved.','The one-key change is what later separates minor and major triads.'),
('IPV-25','Fourth, tritone, fifth','IPV-25-native','IPV-25','Five, six and seven semitones above C: F, F♯ (or G♭) and G, three neighbouring keys.','Play C with F, with F♯, then with G.','Not a ranking; the tritone name depends on spelling.'),
('IPV-26','Minor versus major sixth','IPV-26-native','IPV-18+IPV-19','Keep C. A♭ is eight semitones above, A is nine.','Play C with A♭, then C with A.','Warm or wistful words, if any, are invitations, not facts.'),
('IPV-27','Minor versus major seventh','IPV-27-native','IPV-20+IPV-21','Keep C. B♭ is ten semitones above, B is eleven. Neither is the octave.','Play C with B♭, then with B, then with the C above.','C to B is 11 semitones; the melodic B up to C is one semitone.'),
('IPV-28','Context changes what we hear','IPV-28-native','IPV-28','The same perfect fifth, 7 semitones, built in three registers. The key pattern is identical.','Play C with G low on your keyboard, then in the middle, then high.','No universal consonance scale; register, timbre and context all matter.'),
('IPV-29','Interval inversion','IPV-29-native','IPV-29','Move the lower note up an octave: a minor third becomes a major sixth. The semitones add to 12 and the interval numbers add to 9.','Play C with E♭, then E♭ with the C above. Count 3 then 9.','Names invert in specific pairs: m3↔M6, M3↔m6, P4↔P5.'),
('IPV-30','Thirteen-landmark map','IPV-30-native','IPV-30','All thirteen intervals with names and note pairs on one exact ruler. The painting is a journey, not a scale.','Choose one landmark, find it on your keyboard and play its two notes.','Positions are exact semitones; the painting does not encode distance.')]
page('comparisons.html','Comparisons and synthesis',''.join(item(i,t,'COMPARE',a,n,h,o,g,'wide') for i,t,n,a,h,o,g in C),'Paired-family comparisons, the register comparison, inversion and the thirteen-landmark map. IPV-23, 24, 26, 27 are recomposed from the interval art (no extra model calls).')
# ---------- support
ic=''.join(f'<figure><img src="../derived/IPV-31-icon-{10+c["semitones"]}.webp" alt=""><figcaption>{c["abbreviation"]}</figcaption></figure>' for c in D)
LAY=[('A','Smooth, rough or fused sounds','IPV-28'),('B','How the interval gets its real name','IPV-08'),('C','Inversion, the octave’s hidden symmetry','IPV-29'),('D','The third note changes a world','IPV-08'),('E','Paint your own palette','IPV-30'),('F','The wider musical world','IPV-01')]
lay=''.join(f'<div class="card"><p class="eyebrow">Atlas layer {k}</p><img class="banner" src="../art/{a}.webp" alt="" aria-hidden="true"><p class="how">{html.escape(AT["layers"][i]["title"])}</p></div>' for i,(k,t,a) in enumerate(LAY))
sup=f'''<section class="item"><p class="eyebrow">IPV-02 · IPV-03 · variants</p><h2>Card and chapter art (13 each, derived from the interval art, no model call)</h2><div class="grid">'''+''.join(f'<div class="card"><img class="banner" src="../derived/IPV-02-card-{n}.webp" alt="" aria-hidden="true"><img class="banner" src="../derived/IPV-03-chapter-{n}.webp" alt="" aria-hidden="true"><p class="meta">IPV-{n}</p></div>' for n in (10,14,17,22))+'</div></section>'
sup+=f'<section class="item"><p class="eyebrow">IPV-31 · micro-icon family</p><h2>Thirteen icons (96px crops; the native name always accompanies each)</h2><div class="icons">{ic}</div></section>'
sup+='<section class="item"><p class="eyebrow">IPV-32 · section mini-banners</p><h2>Four banners</h2><div class="grid">'+''.join(f'<img class="banner" src="../derived/IPV-32-banner-{k}.webp" alt="" aria-hidden="true">' for k in ('01','04','05','08'))+'</div></section>'
sup+=item('IPV-34','Same key, two interval names (new: Atlas layer B)','SUPPORT · NATIVE (+ IPV-08 art)','IPV-08','IPV-34-native','The same two keys carry two correct names depending on how the upper note is spelled. Counting letters decides the interval number.','Play C and the black key above D. Say it as C to E♭, then as C to D♯: same keys, two names.','Added to the IPV sequence because Atlas layer B teaches naming and no listed visual covered it.','wide')
sup+=item('IPV-35','The third note changes a world (new: Atlas layer D)','SUPPORT · NATIVE (+ IPV-08 art)','IPV-08','IPV-35-native','Start from two notes, add a third, then change one key. The structure shows exactly which keys form each shape.','Play C and E together, add G, then replace E with E♭ and listen to how the shape changes.','Added for Atlas layer D. Not placed in Lesson 2A.','wide')
sup+='<section class="item"><p class="eyebrow">Atlas layers A–F · placement</p><h2>Six wider Atlas sections: which art each uses</h2><div class="grid">'+lay+'</div></section>'
page('support.html','Support visuals',sup,'Card and chapter variants, icons, banners, the two added naming/triad figures and the six wider Atlas sections. IPV-33 (six door motifs) is deferred pending a content decision.')
# ---------- assembled
ch=AT['chapters'][4]; cd=D[4]
heads=['Meet the interval','As a moving melody','Two notes together','In actual music']
chap=''.join(f'<h3>{h}</h3><p>{html.escape(ch[h])}</p>' for h in heads)
asm=f'''<section class="item"><p class="eyebrow">Sample 1 · landing</p><h2>Interval Palette</h2><img class="banner" style="max-width:760px;margin:0 auto" src="../art/IPV-01.webp" alt="" aria-hidden="true"><img class="nat" style="width:100%;max-width:920px;margin:6px auto 0;display:block" src="../native/IPV-07-native.svg" alt="{html.escape(desc('IPV-07-native'))}"><div class="icons" style="margin-top:22px">{ic}</div><p class="how">Thirteen landmarks above C. Choose one to explore. Everything on this page is for your own keyboard.</p></section>
<section class="item"><p class="eyebrow">Sample 2 · one card</p><div class="grid"><div class="card"><img class="banner" style="max-width:240px;margin:0 auto" src="../derived/IPV-02-card-14.webp" alt="" aria-hidden="true"><img class="nat" style="width:100%;display:block" src="../native/IPV-14-native.svg" alt="{html.escape(desc('IPV-14-native'))}"><p class="how">{ch["words"]} · {ch["example"]}</p></div></div></section>
<section class="item"><p class="eyebrow">Sample 3 · deep chapter (source copy retained)</p><h2>{ch["name"]}</h2><div class="row"><img class="banner" src="../derived/IPV-03-chapter-14.webp" alt="" aria-hidden="true"><img class="nat" style="width:100%;display:block" src="../native/IPV-14-native.svg" alt="{html.escape(desc('IPV-14-native'))}"></div><div class="ch">{chap}<h3>On your own keyboard</h3><p>Find C4 and play it, then E4. Count four keys. Now lower E to E♭ and count three. Which one do you want to use in the next thing you write? There is no wrong answer.</p><div class="src"><p class="meta">Source "Listen and create" and "Paint What You Hear" sections are retained in the source JSON and will be adapted to real-instrument wording at integration.</p></div></div></section>'''
page('assembled.html','Assembled samples',asm,'Three compositions in the light Ajourné page language: landing, one card and one deep chapter, using the real source copy.')
print('pages written')
